/**
 * Attach event callback for a weapon instance.
 * Called when main thread registers first listener for an event type.
 *
 * @param {string} eventType - Event type ('fire', 'hit', 'explode', 'spawn', 'despawn')
 * @param {number} weaponIndex - Weapon instance index
 */
export function attachWeaponEventCB(eventType: string, weaponIndex: number): void;
/**
 * Detach event callback for a weapon instance.
 * Called when main thread removes last listener for an event type.
 *
 * @param {string} eventType - Event type ('fire', 'hit', 'explode', 'spawn', 'despawn')
 * @param {number} weaponIndex - Weapon instance index
 */
export function detachWeaponEventCB(eventType: string, weaponIndex: number): void;
export namespace weaponEventBindings {
    let fire: Map<any, any>;
    let hit: Map<any, any>;
    let explode: Map<any, any>;
    let spawn: Map<any, any>;
    let despawn: Map<any, any>;
}
